[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>SnapFrame — Capture, Create &amp; Share What You Love</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:ital,wght@0,300;0,400;0,500;0,600;0,700;0,800;1,400&display=swap" rel="stylesheet" />
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --black: #000000;
      --purple: #7638FA;
      --purple-light: #9B6BFF;
      --purple-pale: #F0EAFF;
      --orange: #FF7A00;
      --orange-light: #FF9A3C;
      --orange-pale: #FFF3E8;
      --white: #FFFFFF;
      --gray-50: #FAFAFA;
      --gray-100: #F4F4F5;
      --gray-200: #E4E4E7;
      --gray-400: #A1A1AA;
      --gray-600: #52525B;
      --gray-800: #27272A;
      --radius-sm: 0.5rem;
      --radius-md: 1rem;
      --radius-lg: 1.5rem;
      --radius-xl: 2rem;
      --font: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: var(--font);
      background: var(--white);
      color: var(--black);
      line-height: 1.6;
      overflow-x: hidden;
    }

    a { color: inherit; text-decoration: none; }
    img { display: block; max-width: 100%; }
    button { cursor: pointer; font-family: var(--font); border: none; background: none; }

    /* ── HEADER ─────────────────────────────────── */
    .header {
      position: sticky;
      top: 0;
      z-index: 100;
      background: rgba(255,255,255,0.92);
      backdrop-filter: blur(12px);
      -webkit-backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--gray-100);
      padding: 0 1.5rem;
      height: 64px;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .header-logo {
      display: flex;
      align-items: center;
      gap: 0.5rem;
      font-weight: 800;
      font-size: 1.25rem;
      letter-spacing: -0.02em;
    }

    .header-logo-icon {
      width: 36px;
      height: 36px;
      border-radius: 10px;
      background: linear-gradient(135deg, var(--purple) 0%, var(--orange) 100%);
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
    }

    .header-logo-icon svg { width: 20px; height: 20px; fill: white; }

    .header-right {
      display: flex;
      align-items: center;
      gap: 1rem;
    }

    .btn-login {
      padding: 0.5rem 1.25rem;
      background: var(--black);
      color: var(--white);
      border-radius: 100px;
      font-size: 0.875rem;
      font-weight: 600;
      transition: background 150ms, transform 100ms;
    }
    .btn-login:hover { background: var(--gray-800); transform: translateY(-1px); }
    .btn-login:active { transform: scale(0.97); }

    .hamburger {
      width: 40px;
      height: 40px;
      display: none;
      flex-direction: column;
      justify-content: center;
      align-items: center;
      gap: 5px;
      border-radius: var(--radius-sm);
      transition: background 150ms;
    }
    .hamburger:hover { background: var(--gray-100); }
    .hamburger span {
      display: block;
      width: 22px;
      height: 2px;
      background: var(--black);
      border-radius: 2px;
      transition: transform 300ms ease, opacity 200ms;
    }
    .hamburger.open span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
    .hamburger.open span:nth-child(2) { opacity: 0; transform: scaleX(0); }
    .hamburger.open span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

    /* Mobile nav overlay */
    .mobile-nav {
      display: none;
      position: fixed;
      top: 64px;
      left: 0;
      right: 0;
      bottom: 0;
      background: var(--white);
      z-index: 99;
      padding: 2rem 1.5rem;
      flex-direction: column;
      gap: 0.5rem;
      overflow-y: auto;
      transform: translateY(-8px);
      opacity: 0;
      transition: transform 300ms ease, opacity 250ms ease;
    }
    .mobile-nav.open {
      display: flex;
      transform: translateY(0);
      opacity: 1;
    }
    .mobile-nav a {
      font-size: 1.125rem;
      font-weight: 600;
      padding: 0.75rem 0;
      border-bottom: 1px solid var(--gray-100);
      color: var(--gray-800);
      transition: color 150ms;
    }
    .mobile-nav a:hover { color: var(--purple); }
    .mobile-nav .mobile-login {
      margin-top: 1rem;
      padding: 0.875rem;
      background: var(--black);
      color: var(--white);
      border-radius: var(--radius-md);
      text-align: center;
      font-weight: 700;
    }

    /* ── HERO ────────────────────────────────────── */
    .hero {
      position: relative;
      overflow: hidden;
      padding: 6rem 1.5rem 5rem;
      text-align: center;
      background: var(--white);
    }

    .hero-bg {
      position: absolute;
      inset: 0;
      pointer-events: none;
      overflow: hidden;
    }
    .hero-blob {
      position: absolute;
      border-radius: 50%;
      filter: blur(80px);
      opacity: 0.18;
    }
    .hero-blob-1 {
      width: 600px; height: 600px;
      background: var(--purple);
      top: -200px; left: -150px;
    }
    .hero-blob-2 {
      width: 500px; height: 500px;
      background: var(--orange);
      top: -100px; right: -100px;
    }
    .hero-blob-3 {
      width: 400px; height: 400px;
      background: var(--purple-light);
      bottom: -100px; left: 50%;
      transform: translateX(-50%);
    }

    .hero-content {
      position: relative;
      max-width: 800px;
      margin: 0 auto;
    }

    .hero-eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      background: var(--purple-pale);
      color: var(--purple);
      border-radius: 100px;
      padding: 0.375rem 1rem;
      font-size: 0.8125rem;
      font-weight: 700;
      letter-spacing: 0.04em;
      text-transform: uppercase;
      margin-bottom: 1.5rem;
    }

    .hero-title {
      font-size: clamp(2.25rem, 5.5vw, 4rem);
      font-weight: 800;
      line-height: 1.1;
      letter-spacing: -0.03em;
      color: var(--black);
      margin-bottom: 1.5rem;
    }

    .hero-title .gradient-text {
      background: linear-gradient(135deg, var(--purple) 0%, var(--orange) 100%);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    .hero-cta {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      padding: 0.875rem 2rem;
      background: linear-gradient(135deg, var(--purple) 0%, var(--orange) 100%);
      color: var(--white);
      border-radius: 100px;
      font-size: 1rem;
      font-weight: 700;
      margin-top: 0.5rem;
      transition: transform 150ms, box-shadow 150ms;
      box-shadow: 0 4px 20px rgba(118, 56, 250, 0.35);
    }
    .hero-cta:hover { transform: translateY(-2px); box-shadow: 0 8px 30px rgba(118, 56, 250, 0.45); }
    .hero-cta:active { transform: scale(0.97); }

    .hero-image-row {
      display: flex;
      justify-content: center;
      gap: 1rem;
      margin-top: 4rem;
      padding: 0 1rem;
    }

    .hero-phone {
      width: 180px;
      height: 320px;
      border-radius: 24px;
      overflow: hidden;
      box-shadow: 0 20px 60px rgba(0,0,0,0.15);
      flex-shrink: 0;
      position: relative;
    }
    .hero-phone:nth-child(1) { transform: rotate(-4deg) translateY(20px); }
    .hero-phone:nth-child(3) { transform: rotate(4deg) translateY(20px); }
    .hero-phone img { width: 100%; height: 100%; object-fit: cover; }

    /* ── SECTIONS SHARED ─────────────────────────── */
    .section {
      padding: 5rem 1.5rem;
    }

    .section-inner {
      max-width: 1100px;
      margin: 0 auto;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 4rem;
      align-items: center;
    }

    .section-inner.reverse { direction: rtl; }
    .section-inner.reverse > * { direction: ltr; }

    .section-tag {
      display: inline-block;
      font-size: 0.75rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      padding: 0.25rem 0.75rem;
      border-radius: 100px;
      margin-bottom: 1rem;
    }

    .section-headline {
      font-size: clamp(1.5rem, 3vw, 2.25rem);
      font-weight: 800;
      line-height: 1.2;
      letter-spacing: -0.025em;
      margin-bottom: 1rem;
    }

    .section-desc {
      font-size: 1rem;
      line-height: 1.75;
      color: var(--gray-600);
      margin-bottom: 1.5rem;
    }

    .section-link {
      display: inline-flex;
      align-items: center;
      gap: 0.375rem;
      font-weight: 700;
      font-size: 0.9375rem;
      border-bottom: 2px solid currentColor;
      padding-bottom: 1px;
      transition: gap 150ms;
    }
    .section-link:hover { gap: 0.625rem; }

    .section-visual {
      border-radius: var(--radius-xl);
      overflow: hidden;
      aspect-ratio: 4/3;
      position: relative;
    }
    .section-visual img {
      width: 100%;
      height: 100%;
      object-fit: cover;
      transition: transform 400ms ease;
    }
    .section-visual:hover img { transform: scale(1.03); }

    /* Features */
    .features-section {
      background: var(--gray-50);
    }
    .features-section .section-tag {
      background: var(--purple-pale);
      color: var(--purple);
    }
    .features-section .section-link { color: var(--purple); }
    .features-section .section-visual {
      box-shadow: 0 24px 60px rgba(118,56,250,0.18);
    }

    /* Safety */
    .safety-section .section-tag {
      background: #E8F5E9;
      color: #2E7D32;
    }
    .safety-section .section-link { color: #2E7D32; }
    .safety-section .section-visual {
      box-shadow: 0 24px 60px rgba(46,125,50,0.12);
    }

    /* Creators */
    .creators-section {
      background: var(--gray-50);
    }
    .creators-section .section-tag {
      background: var(--orange-pale);
      color: var(--orange);
    }
    .creators-section .section-link { color: var(--orange); }
    .creators-section .section-visual {
      box-shadow: 0 24px 60px rgba(255,122,0,0.18);
    }

    /* ── TAGLINE BANNER ──────────────────────────── */
    .tagline-banner {
      padding: 5rem 1.5rem;
      text-align: center;
      background: linear-gradient(135deg, var(--purple) 0%, #B44FFF 50%, var(--orange) 100%);
      position: relative;
      overflow: hidden;
    }

    .tagline-banner::before {
      content: '';
      position: absolute;
      inset: 0;
      background: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='none' fill-rule='evenodd'%3E%3Cg fill='%23ffffff' fill-opacity='0.05'%3E%3Ccircle cx='30' cy='30' r='2'/%3E%3C/g%3E%3C/g%3E%3C/svg%3E");
    }

    .tagline-text {
      position: relative;
      font-size: clamp(2rem, 5vw, 3.5rem);
      font-weight: 800;
      color: var(--white);
      line-height: 1.15;
      letter-spacing: -0.03em;
      max-width: 700px;
      margin: 0 auto;
    }

    /* ── NEWS ────────────────────────────────────── */
    .news-section {
      padding: 5rem 0 5rem;
      overflow: hidden;
    }

    .news-header {
      display: flex;
      justify-content: space-between;
      align-items: flex-end;
      padding: 0 1.5rem;
      max-width: 1100px;
      margin: 0 auto 2.5rem;
    }

    .news-label {
      display: inline-block;
      font-size: 0.75rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--purple);
      margin-bottom: 0.5rem;
    }

    .news-heading {
      font-size: clamp(1.75rem, 3vw, 2.5rem);
      font-weight: 800;
      letter-spacing: -0.025em;
      line-height: 1.15;
    }

    .news-view-more {
      display: inline-flex;
      align-items: center;
      gap: 0.375rem;
      font-weight: 700;
      font-size: 0.9375rem;
      color: var(--purple);
      border-bottom: 2px solid var(--purple);
      padding-bottom: 1px;
      white-space: nowrap;
      flex-shrink: 0;
      transition: gap 150ms;
    }
    .news-view-more:hover { gap: 0.625rem; }

    .news-carousel-wrap {
      position: relative;
    }

    .news-carousel {
      display: flex;
      gap: 1.25rem;
      padding: 1rem 1.5rem 2rem;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      -webkit-overflow-scrolling: touch;
      scrollbar-width: none;
      cursor: grab;
    }
    .news-carousel::-webkit-scrollbar { display: none; }
    .news-carousel.grabbing { cursor: grabbing; }

    .news-card {
      flex: 0 0 300px;
      scroll-snap-align: start;
      background: var(--white);
      border-radius: var(--radius-lg);
      overflow: hidden;
      border: 1px solid var(--gray-200);
      transition: transform 200ms ease, box-shadow 200ms ease;
    }
    .news-card:hover {
      transform: translateY(-4px);
      box-shadow: 0 16px 40px rgba(0,0,0,0.1);
    }

    .news-card-thumb {
      width: 100%;
      height: 180px;
      overflow: hidden;
      background: var(--gray-100);
      position: relative;
    }
    .news-card-thumb img {
      width: 100%; height: 100%;
      object-fit: cover;
      transition: transform 400ms ease;
    }
    .news-card:hover .news-card-thumb img { transform: scale(1.05); }

    .news-card-body {
      padding: 1.25rem;
    }

    .news-card-tags {
      display: flex;
      flex-wrap: wrap;
      gap: 0.375rem;
      margin-bottom: 0.75rem;
    }

    .news-tag {
      font-size: 0.6875rem;
      font-weight: 700;
      letter-spacing: 0.05em;
      text-transform: uppercase;
      color: var(--purple);
      background: var(--purple-pale);
      border-radius: 100px;
      padding: 0.2rem 0.625rem;
    }
    .news-tag.orange {
      color: var(--orange);
      background: var(--orange-pale);
    }
    .news-tag.green {
      color: #2E7D32;
      background: #E8F5E9;
    }

    .news-card-title {
      font-size: 0.9375rem;
      font-weight: 700;
      line-height: 1.4;
      margin-bottom: 0.75rem;
      color: var(--black);
      display: -webkit-box;
      -webkit-line-clamp: 3;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }

    .news-card-date {
      font-size: 0.8125rem;
      color: var(--gray-400);
      font-weight: 500;
    }

    /* Scroll arrows */
    .carousel-arrow {
      position: absolute;
      top: 50%;
      transform: translateY(-50%);
      width: 44px;
      height: 44px;
      border-radius: 50%;
      background: var(--white);
      border: 1px solid var(--gray-200);
      display: flex;
      align-items: center;
      justify-content: center;
      cursor: pointer;
      box-shadow: 0 2px 12px rgba(0,0,0,0.1);
      transition: background 150ms, transform 150ms, box-shadow 150ms;
      z-index: 2;
    }
    .carousel-arrow:hover {
      background: var(--purple);
      border-color: var(--purple);
      box-shadow: 0 4px 20px rgba(118,56,250,0.3);
    }
    .carousel-arrow:hover svg { stroke: white; }
    .carousel-arrow:active { transform: translateY(-50%) scale(0.95); }
    .carousel-arrow svg { stroke: var(--gray-600); transition: stroke 150ms; }
    .carousel-arrow-left { left: 0.75rem; }
    .carousel-arrow-right { right: 0.75rem; }

    /* ── CTA DOWNLOAD ────────────────────────────── */
    .cta-download {
      padding: 5rem 1.5rem;
      text-align: center;
      background: var(--black);
      color: var(--white);
      position: relative;
      overflow: hidden;
    }

    .cta-download::before {
      content: '';
      position: absolute;
      width: 600px; height: 600px;
      background: radial-gradient(circle, var(--purple) 0%, transparent 70%);
      top: -200px; left: -100px;
      opacity: 0.25;
    }
    .cta-download::after {
      content: '';
      position: absolute;
      width: 500px; height: 500px;
      background: radial-gradient(circle, var(--orange) 0%, transparent 70%);
      bottom: -200px; right: -100px;
      opacity: 0.2;
    }

    .cta-content { position: relative; }

    .cta-headline {
      font-size: clamp(2rem, 5vw, 3.5rem);
      font-weight: 800;
      letter-spacing: -0.03em;
      line-height: 1.1;
    }

    .cta-subheadline {
      font-size: clamp(1.5rem, 3vw, 2.5rem);
      font-weight: 800;
      letter-spacing: -0.025em;
      background: linear-gradient(135deg, var(--purple-light) 0%, var(--orange-light) 100%);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
      margin-bottom: 2.5rem;
    }

    .cta-buttons {
      display: flex;
      justify-content: center;
      gap: 1rem;
      flex-wrap: wrap;
    }

    .store-btn {
      display: inline-flex;
      align-items: center;
      gap: 0.75rem;
      padding: 0.875rem 1.5rem;
      background: var(--white);
      color: var(--black);
      border-radius: var(--radius-md);
      font-weight: 700;
      font-size: 0.9375rem;
      transition: transform 150ms, box-shadow 150ms;
      box-shadow: 0 2px 12px rgba(0,0,0,0.2);
    }
    .store-btn:hover {
      transform: translateY(-2px);
      box-shadow: 0 8px 24px rgba(0,0,0,0.3);
    }
    .store-btn:active { transform: scale(0.97); }
    .store-btn svg { flex-shrink: 0; }
    .store-btn-text-top { font-size: 0.6875rem; font-weight: 500; opacity: 0.7; display: block; }
    .store-btn-text-main { font-size: 1rem; font-weight: 800; display: block; }

    /* ── FOOTER ──────────────────────────────────── */
    .footer {
      background: var(--gray-50);
      border-top: 1px solid var(--gray-200);
      padding: 4rem 1.5rem 2rem;
    }

    .footer-inner {
      max-width: 1100px;
      margin: 0 auto;
    }

    .footer-logo {
      display: flex;
      align-items: center;
      gap: 0.5rem;
      font-weight: 800;
      font-size: 1.125rem;
      margin-bottom: 2.5rem;
    }

    .footer-logo-icon {
      width: 32px; height: 32px;
      border-radius: 8px;
      background: linear-gradient(135deg, var(--purple) 0%, var(--orange) 100%);
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .footer-logo-icon svg { width: 18px; height: 18px; fill: white; }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(6, 1fr);
      gap: 2rem;
      padding-bottom: 3rem;
      border-bottom: 1px solid var(--gray-200);
    }

    .footer-col-title {
      font-size: 0.75rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      color: var(--black);
      margin-bottom: 1rem;
    }

    .footer-col ul {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 0.5rem;
    }

    .footer-col ul li a {
      font-size: 0.875rem;
      color: var(--gray-600);
      transition: color 150ms;
      display: inline-flex;
      align-items: center;
      gap: 0.25rem;
    }
    .footer-col ul li a:hover { color: var(--purple); }

    .footer-bottom {
      display: flex;
      align-items: center;
      justify-content: space-between;
      flex-wrap: wrap;
      gap: 1.5rem;
      padding-top: 2rem;
    }

    .footer-lang {
      display: inline-flex;
      align-items: center;
      gap: 0.375rem;
      font-size: 0.875rem;
      color: var(--gray-600);
      font-weight: 500;
      padding: 0.375rem 0.75rem;
      border: 1px solid var(--gray-200);
      border-radius: 100px;
      cursor: pointer;
      transition: border-color 150ms;
    }
    .footer-lang:hover { border-color: var(--purple); color: var(--purple); }

    .footer-social {
      display: flex;
      align-items: center;
      gap: 0.625rem;
    }

    .social-icon {
      width: 36px; height: 36px;
      border-radius: 50%;
      background: var(--white);
      border: 1px solid var(--gray-200);
      display: flex;
      align-items: center;
      justify-content: center;
      transition: background 150ms, border-color 150ms, transform 150ms;
    }
    .social-icon:hover {
      background: var(--purple);
      border-color: var(--purple);
      transform: translateY(-2px);
    }
    .social-icon:hover svg { stroke: white; fill: none; }
    .social-icon svg { width: 16px; height: 16px; stroke: var(--gray-600); fill: none; stroke-width: 1.75; transition: stroke 150ms; }

    .footer-legal {
      display: flex;
      align-items: center;
      gap: 0.5rem;
      flex-wrap: wrap;
    }

    .footer-legal a {
      font-size: 0.8125rem;
      color: var(--gray-400);
      transition: color 150ms;
    }
    .footer-legal a:hover { color: var(--gray-800); }
    .footer-legal span { color: var(--gray-300); }

    /* ── RESPONSIVE ──────────────────────────────── */
    @media (max-width: 1024px) {
      .footer-grid { grid-template-columns: repeat(3, 1fr); }
    }

    @media (max-width: 768px) {
      .hamburger { display: flex; }

      .section-inner {
        grid-template-columns: 1fr;
        gap: 2rem;
      }
      .section-inner.reverse { direction: ltr; }

      .hero-image-row {
        gap: 0.5rem;
      }
      .hero-phone { width: 130px; height: 240px; }
      .hero-phone:nth-child(1) { transform: rotate(-3deg) translateY(12px); }
      .hero-phone:nth-child(3) { transform: rotate(3deg) translateY(12px); }

      .news-header {
